import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.vLhlLNVn.js";const i="/assets/datentypen.EbM86bxg.svg",u=JSON.parse('{"title":"Log messages","description":"","frontmatter":{"order":3,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/03.referenz/03.log-meldungen.md"},"headers":[],"relativePath":"adapter/wled/referenz/log-meldungen.md","filePath":"adapter/wled/referenz/log-meldungen.md","lastUpdated":null}'),n={name:"adapter/wled/referenz/log-meldungen.md"};function r(d,e,h,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="log-messages" tabindex="-1">Log messages <a class="header-anchor" href="#log-messages" aria-label="Permalink to &quot;Log messages&quot;">​</a></h1><p><a id="warning-state-attribute-definition-missing"></a></p><h2 id="what-does-the-warning-state-attribute-definition-missing-mean" tabindex="-1">What does the warning &quot;State attribute definition missing&quot; mean? <a class="header-anchor" href="#what-does-the-warning-state-attribute-definition-missing-mean" aria-label="Permalink to &quot;What does the warning &quot;State attribute definition missing&quot; mean?&quot;">​</a></h2><p><strong>In short:</strong> The message is harmless; you don&#39;t need to do anything. WLED delivers a field for which the adapter has no description of its own. The adapter creates the state anyway. Since v0.7.1 the message only appears at the log level &quot;debug&quot;.</p><p>This is what the message looks like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State attribute definition missing for : &lt;field&gt; with value : &lt;value&gt;</span></span></code></pre></div><h3 id="what-is-behind-it" tabindex="-1">What is behind it <a class="header-anchor" href="#what-is-behind-it" aria-label="Permalink to &quot;What is behind it&quot;">​</a></h3><p>The adapter has a list of all WLED fields it knows. For each field, the list holds the name, the data type, the role and whether you may write the state. If a new WLED firmware brings a field that is missing from the list, the adapter creates the state like this:</p><ul><li>The name is the field name from WLED.</li><li>The data type follows the value WLED delivers.</li><li>The state is read-only. You can&#39;t write through this state.</li></ul><p>Examples from the past are <code>cct</code>, <code>n</code> and <code>liveseg</code>. They came with new WLED versions and are in the list by now.</p><p>If you want to set such a field anyway, send it as a JSON command via the <code>action</code> state. If a field is missing for good, report it in a <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub issue</a>.</p><h3 id="older-versions" tabindex="-1">Older versions <a class="header-anchor" href="#older-versions" aria-label="Permalink to &quot;Older versions&quot;">​</a></h3><p><strong>Up to v0.7.0:</strong> The message appeared as a warning or error in the normal log, sometimes with the addition <code>Sentry disabled, error caught</code>. In v0.5.x the instance could stop afterwards. In that case, update the adapter.</p><p><strong>Up to v0.9.2:</strong> At the level &quot;debug&quot;, the message appears in the log again on every update from the device, over and over for the same field.</p><p><strong>From v0.9.3:</strong> The adapter reports each missing field only once per start (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/917" target="_blank" rel="noreferrer">#917</a>).</p><p><strong>See also:</strong> <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">How do I send a complete JSON command to WLED from ioBroker?</a> · <a href="./../fehlerbehebung/verbindung-und-start#adapter-stop-working-after-wled">Why does the adapter stop working after a WLED firmware update?</a></p><p><a id="warnings-about-wrong-data-type"></a></p><h2 id="what-do-warnings-about-a-wrong-data-type-or-a-missing-val-mean-when-writing-states" tabindex="-1">What do warnings about a wrong data type or a missing &quot;val&quot; mean when writing states? <a class="header-anchor" href="#what-do-warnings-about-a-wrong-data-type-or-a-missing-val-mean-when-writing-states" aria-label="Permalink to &quot;What do warnings about a wrong data type or a missing &quot;val&quot; mean when writing states?&quot;">​</a></h2><p><strong>In short:</strong> ioBroker checks every value written to a state against the state&#39;s data type. If the type doesn&#39;t match, the log shows a warning. If it comes from your script, you are writing the value in the wrong type, for example <code>&quot;true&quot;</code> as text instead of <code>true</code>. If it comes from the adapter itself, an update helps.</p><p>This is what the messages look like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State value to set for &quot;wled.0.&lt;MAC&gt;.&lt;State&gt;&quot; has to be type &quot;boolean&quot; but received type &quot;string&quot;</span></span>
<span class="line"><span>State value to set for &quot;wled.0.&lt;MAC&gt;.&lt;State&gt;&quot; has to be one of type &quot;string&quot;, &quot;number&quot;, &quot;boolean&quot; but received type &quot;object&quot;</span></span>
<span class="line"><span>State value to set is invalid for wled.0.&lt;MAC&gt;.&lt;State&gt;: The state is missing the required property val!</span></span></code></pre></div><p>The start of the log line shows who wrote the value. If it says <code>wled.&lt;instance&gt;</code>, the value comes from the adapter. If it says, for example, <code>javascript.0</code>, it comes from your script.</p><h3 id="which-data-type-do-the-states-expect" tabindex="-1">Which data type do the states expect? <a class="header-anchor" href="#which-data-type-do-the-states-expect" aria-label="Permalink to &quot;Which data type do the states expect?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Type</th><th>Example</th></tr></thead><tbody><tr><td><code>on</code></td><td>boolean</td><td><code>true</code> or <code>false</code></td></tr><tr><td><code>bri</code></td><td>number</td><td><code>0</code> to <code>255</code></td></tr><tr><td><code>ps</code></td><td>number</td><td><code>3</code> for preset 3</td></tr><tr><td><code>pl</code></td><td>number</td><td><code>1</code> for playlist 1</td></tr><tr><td><code>transition</code></td><td>number</td><td><code>7</code></td></tr><tr><td><code>seg.&lt;segment&gt;.col.0</code>, <code>.1</code>, <code>.2</code></td><td>text with numbers in square brackets</td><td><code>&quot;[255,0,0]&quot;</code> or with white channel <code>&quot;[255,0,0,0]&quot;</code></td></tr><tr><td><code>seg.&lt;segment&gt;.col.0_HEX</code>, <code>.1_HEX</code>, <code>.2_HEX</code></td><td>text</td><td><code>&quot;#ff0000&quot;</code></td></tr><tr><td><code>action</code></td><td>text containing JSON</td><td><code>{&quot;on&quot;:true,&quot;bri&quot;:128}</code> as text</td></tr><tr><td><code>_info._online</code></td><td>boolean, read-only</td><td><code>true</code> or <code>false</code></td></tr></tbody></table><p>The adapter sets the types of <code>on</code>, <code>bri</code>, <code>ps</code>, <code>pl</code> and <code>transition</code> when it creates them, based on the value WLED delivers. The color states are of type &quot;mixed&quot; and hold the color as text. When writing, the adapter also accepts <code>&quot;255,0,0&quot;</code> without brackets.</p><h3 id="how-to-write-the-values-in-the-right-type" tabindex="-1">How to write the values in the right type <a class="header-anchor" href="#how-to-write-the-values-in-the-right-type" aria-label="Permalink to &quot;How to write the values in the right type&quot;">​</a></h3><p>In a script, pass numbers and booleans without quotes, and colors as text:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.on&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// not &#39;true&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.bri&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// not &#39;128&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.ps&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// not &#39;3&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.seg.0.col.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[255,0,0]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// text, not an array</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.seg.0.col.0_HEX&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#ff0000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>In Blockly, the block you attach to &quot;control&quot; or &quot;update&quot; decides the type:</p><ol><li>For <code>on</code>, use the logic block &quot;true&quot; or &quot;false&quot;. A text block containing <code>true</code> delivers text.</li><li>For <code>bri</code>, <code>ps</code> and <code>pl</code>, use the number block from &quot;Math&quot;. A text block containing <code>3</code> delivers text.</li><li>For colors, use a text block with <code>[255,0,0]</code> or <code>#ff0000</code>. A list block delivers a list, so the type &quot;object&quot;.</li></ol><p><img src="`+i+'" alt="Overview: the logic block &quot;true&quot; or &quot;false&quot; delivers a boolean for on. The number block delivers a number for bri, ps, pl and transition. A text block delivers text for the color states. A text block with true on on, and a list block on a color, lead to a warning."></p><h3 id="messages-from-the-adapter-itself" tabindex="-1">Messages from the adapter itself <a class="header-anchor" href="#messages-from-the-adapter-itself" aria-label="Permalink to &quot;Messages from the adapter itself&quot;">​</a></h3><p><strong>Up to v0.9.2:</strong> If a device can&#39;t be reached, the adapter writes <code>_info._online</code> as text. The log then shows <code>State value to set for &quot;wled.0.&lt;MAC&gt;._info._online&quot; has to be type &quot;boolean&quot; but received type &quot;string&quot;</code>. You don&#39;t need to change anything; the message comes from the adapter.</p><p><strong>From v0.9.3:</strong> <code>_info._online</code> is always a boolean, and the message no longer appears (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/794" target="_blank" rel="noreferrer">#794</a>).</p><p>The message <code>The state is missing the required property val!</code> and type messages about states under <code>_info</code> such as <code>_info.mac</code> came from adapter versions from 2020 and 2021. Today the adapter skips empty values. If you still see these messages, update the adapter.</p><h3 id="states-that-change-with-v0-9-3" tabindex="-1">States that change with v0.9.3 <a class="header-anchor" href="#states-that-change-with-v0-9-3" aria-label="Permalink to &quot;States that change with v0.9.3&quot;">​</a></h3><p><strong>From v0.9.3:</strong> <code>seg.&lt;segment&gt;.mi</code> (mirror segment) is a boolean and can be written (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/918" target="_blank" rel="noreferrer">#918</a>).</p><p><strong>From v0.9.3:</strong> <code>time</code> is a number (Unix timestamp) and can be written to set the device&#39;s clock (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/919" target="_blank" rel="noreferrer">#919</a>). Up to v0.9.2, <code>time</code> is of type &quot;mixed&quot; and read-only.</p><p><strong>See also:</strong> <a href="./../anleitungen/farbe#write-colour-wled-script-blockly">How do I write a color to WLED from a script or Blockly?</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#script-not-ps-wled-ignores">Why doesn&#39;t my script set ps or on?</a> · <a href="./datenpunkte#individual-wled-states-mean">What do the individual WLED states mean?</a></p><p><a id="errors-about-unreachable-devices-websocket"></a></p><h2 id="what-do-the-errors-device-not-reachable-and-websocket-was-closed-before-the-connection-was-established-mean" tabindex="-1">What do the errors &quot;device not reachable&quot; and &quot;WebSocket was closed before the connection was established&quot; mean? <a class="header-anchor" href="#what-do-the-errors-device-not-reachable-and-websocket-was-closed-before-the-connection-was-established-mean" aria-label="Permalink to &quot;What do the errors &quot;device not reachable&quot; and &quot;WebSocket was closed before the connection was established&quot; mean?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="sentry-messages-log"></a></p><h2 id="what-are-the-sentry-messages-in-the-log" tabindex="-1">What are the Sentry messages in the log? <a class="header-anchor" href="#what-are-the-sentry-messages-in-the-log" aria-label="Permalink to &quot;What are the Sentry messages in the log?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',45)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
